/* file : FilesMapper.xml, id : insertFile */
INSERT
  INTO TB_MODEL (
              MODEL_SEQ
            , MODEL_NM
            , MODEL_DERPN
            , MODEL_STATUS
            , REG_USER_SEQ
            , REG_IP
            , INDEX_TRGT_COL
            , RLS_YN
            )
       VALUES (
              #{modelSeq}
            , #{modelNm}
            , #{modelDerpn}
            , #{modelStatus}
            , #{loginUserSeq}
            , #{loginUserIp}
            , #{indexTrgtCol}
            , #{rlsYn}
            )

		SELECT LAST_INSERT_ID()

